WITH valid AS (SELECT id, promo_code, starts_on, ends_on, CAST(discount_pct AS INT) AS discount_pct_int, COALESCE(channel, 'N/A') AS channel_clean FROM promotions WHERE ends_on > DATE '2023-07-09' AND channel IS NOT NULL), filtered AS (SELECT *, WEEKOFYEAR(starts_on) AS starts_on_weekofyear FROM valid WHERE ends_on >= DATE '2023-06-07' AND YEAR(starts_on) >= 2025), with_windows AS (SELECT id, starts_on, ends_on, MIN(discount_pct_int) OVER w_running AS running_min_discount_pct_int, MAX(discount_pct_int) OVER w_running AS running_max_discount_pct_int, COUNT(discount_pct_int) OVER w_running AS running_count_discount_pct_int, AVG(discount_pct_int) OVER w_running AS running_avg_discount_pct_int, NTILE(10) OVER (PARTITION BY promo_code ORDER BY starts_on_weekofyear DESC, id ASC) AS starts_on_weekofyear_bucket FROM filtered WINDOW w_running AS (PARTITION BY promo_code ORDER BY discount_pct_int ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), with_windows_promotions AS (SELECT *, ROW_NUMBER() OVER (ORDER BY running_max_discount_pct_int ASC, id ASC) AS event_seq, ROW_NUMBER() OVER (ORDER BY running_max_discount_pct_int DESC, id ASC) AS event_seq_2, FIRST_VALUE(running_max_discount_pct_int, TRUE) OVER (ORDER BY ends_on ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_running_max_discount_pct_int, LAST_VALUE(running_avg_discount_pct_int, TRUE) OVER w_recent AS last_known_running_avg_discount_pct_int, NTILE(3) OVER (ORDER BY running_count_discount_pct_int DESC, id ASC) AS running_count_discount_pct_int_bucket FROM with_windows WINDOW w_recent AS (ORDER BY running_max_discount_pct_int ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), metrics AS (SELECT id, starts_on, running_min_discount_pct_int, running_max_discount_pct_int, running_avg_discount_pct_int, event_seq_2, first_known_running_max_discount_pct_int, running_count_discount_pct_int_bucket, MIN(event_seq) OVER w_grp AS running_min_event_seq, COUNT(event_seq) OVER w_grp AS running_count_event_seq, AVG(event_seq) OVER w_grp AS running_avg_event_seq FROM with_windows_promotions WHERE running_min_discount_pct_int BETWEEN 67 AND 78 WINDOW w_grp AS (ORDER BY running_max_discount_pct_int ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), base AS (SELECT id, starts_on, running_avg_discount_pct_int, event_seq_2, first_known_running_max_discount_pct_int, running_count_discount_pct_int_bucket, running_count_event_seq, running_avg_event_seq, running_min_event_seq + running_max_discount_pct_int AS running_min_event_seq_plus_running_max_discount_pct_int FROM metrics WHERE starts_on >= DATE '2023-06-20') SELECT DATE_TRUNC('WEEK', starts_on) AS week_start, COUNT(*) AS row_count, APPROX_PERCENTILE(running_avg_event_seq, 0.5) AS running_avg_event_seq_p50 FROM base GROUP BY week_start ORDER BY running_avg_event_seq_p50 ASC
